WITH s0 AS (SELECT * FROM features),
s1 AS (SELECT *, (failed_breakout_down_24 = TRUE) AS _condition_0 FROM s0),
s2 AS (SELECT *, (range_position_24 < 0.5) AS _condition_1 FROM s1),
s3 AS (SELECT *, (efficiency_24 < 0.4) AS _condition_2 FROM s2),
s4 AS (SELECT *, (_condition_0 AND _condition_1 AND _condition_2) AS _condition_3 FROM s3),
s5 AS (SELECT *, (range_position_24 < 0.5) AS _condition_4 FROM s4),
s6 AS (SELECT *, (range_position_24 >= 0.0) AS _condition_5 FROM s5),
s7 AS (SELECT *, (efficiency_24 < 0.4) AS _condition_6 FROM s6),
s8 AS (SELECT *, (_condition_4 AND _condition_5 AND _condition_6) AS _condition_7 FROM s7),
s9 AS (SELECT *, CASE WHEN count(_condition_7) OVER (PARTITION BY instrument ORDER BY bar_open_time ROWS BETWEEN 0 PRECEDING AND CURRENT ROW) = 1 THEN bool_and(_condition_7) OVER (PARTITION BY instrument ORDER BY bar_open_time ROWS BETWEEN 0 PRECEDING AND CURRENT ROW) END AS _condition_8 FROM s8),
s10 AS (SELECT *, lag(_condition_3, 1) OVER (PARTITION BY instrument ORDER BY bar_open_time) AND _condition_8 AS _condition_9 FROM s9),
s11 AS (SELECT *, (failed_breakout_up_24 = TRUE) AS _condition_10 FROM s10),
s12 AS (SELECT *, (range_position_24 > 0.5) AS _condition_11 FROM s11),
s13 AS (SELECT *, (efficiency_24 < 0.4) AS _condition_12 FROM s12),
s14 AS (SELECT *, (_condition_10 AND _condition_11 AND _condition_12) AS _condition_13 FROM s13),
s15 AS (SELECT *, (range_position_24 > 0.5) AS _condition_14 FROM s14),
s16 AS (SELECT *, (range_position_24 <= 1.0) AS _condition_15 FROM s15),
s17 AS (SELECT *, (efficiency_24 < 0.4) AS _condition_16 FROM s16),
s18 AS (SELECT *, (_condition_14 AND _condition_15 AND _condition_16) AS _condition_17 FROM s17),
s19 AS (SELECT *, CASE WHEN count(_condition_17) OVER (PARTITION BY instrument ORDER BY bar_open_time ROWS BETWEEN 0 PRECEDING AND CURRENT ROW) = 1 THEN bool_and(_condition_17) OVER (PARTITION BY instrument ORDER BY bar_open_time ROWS BETWEEN 0 PRECEDING AND CURRENT ROW) END AS _condition_18 FROM s18),
s20 AS (SELECT *, lag(_condition_13, 1) OVER (PARTITION BY instrument ORDER BY bar_open_time) AND _condition_18 AS _condition_19 FROM s19),
s21 AS (SELECT *, (range_position_24 >= 0.5) AS _condition_20 FROM s20),
s22 AS (SELECT *, (range_position_24 <= 0.5) AS _condition_21 FROM s21)
SELECT instrument, bar_open_time, bar_close_time, coalesce(_condition_9, FALSE) AS entry_long, coalesce(_condition_19, FALSE) AS entry_short, coalesce(_condition_20, FALSE) AS exit_long, coalesce(_condition_21, FALSE) AS exit_short FROM s22 ORDER BY instrument, bar_open_time
